package com.cryptostrategy.platform.backtesting.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.model.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;
class TradeExecutionPolicyTest{@Test void appliesAdverseSlippageAndFeesOnBothSidesWithoutNegativeCash(){BacktestTestFixture f=new BacktestTestFixture();var assumptions=BacktestAssumptions.mvp(new BigDecimal("1000"),new BigDecimal("0.001"),new BigDecimal("0.01"));var policy=new TradeExecutionPolicy();var candle=f.members.getFirst().candle().candle();Position position=policy.open(candle,new BigDecimal("1000"),assumptions);assertEquals(0,position.entryPrice().value().compareTo(new BigDecimal("101.000000000000")));assertTrue(position.entryNotional().value().add(position.entryFee().value()).compareTo(new BigDecimal("1000.000000000001"))<=0);var closed=policy.close(new BacktestResultId("00000000000000000000000010"),0,position,candle.close(),candle.closeTime(),ExitReason.FORCED_FINAL_CLOSE,assumptions);assertEquals(0,closed.trade().exitPrice().value().compareTo(candle.close().multiply(new BigDecimal("0.99"))));assertEquals(0,closed.trade().totalFee().value().compareTo(closed.trade().entryFee().value().add(closed.trade().exitFee().value())));assertTrue(closed.cash().signum()>=0);}}
